excerpt.text:
    contents: read
  outputs:
    exists: ${{ steps.branch.outputs.exists }}
  steps:
    - name: Check published branch
      id: branch
      uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
      with:
        script: |
          try {
            await github.rest.git.getRef({ ...context.repo, ref: 'heads/gh-pages' });
          } catch (error) {
            if (error.status !== 404) {
              throw error;
            }
            core.setOutput('exists', 'false');
            await core.summary.addRaw('gh-pages は未作成です。導入後のPR作成・push・reopenで初回の解説を生成すると、自動作成されます。').write();
            return;
          }
          core.setOutput('exists', 'true');

deploy:
  needs: site
  if: needs.site.outputs.exists == 'true'
  runs-on: ubuntu-24.04
  timeout-minutes: 10
  permissions:
    contents: read
    pull-requests: write
    pages: write
